<template>
  <div class="demo-page">
    <header>
      <p class="demo-page__eyebrow">远程组件</p>
      <h1 class="demo-page__title">comps-vue3 · TerminalAuth</h1>
      <p class="demo-page__lead">
        来自 video-code 的「终端极客风登录面板」：等宽字体 + 荧光绿 + 四角描边，字段左侧带 shell 提示符
        （<code>root@sys:~$</code> / <code>passwd:</code>），登录与注册之间是 3D 翻转 + 一次辉光闪烁，
        底部三行日志式状态，注册表单还有密码强度条和两次密码一致性校验。
        原 demo 全屏的矩阵雨 / 扫描线属于页面氛围，这里仍由 demo 自己铺背景，组件只保留面板本身。
      </p>
    </header>

    <section class="ta-demo">
      <div class="ta-demo__head">
        <h2 class="demo-page__section-title">默认荧光绿 / 换配色</h2>
        <code class="ta-demo__tag">accent</code>
      </div>
      <p class="demo-card__text">
        左边是原 demo 的荧光绿；右边换成青色并打开面板内的扫描线。点「&gt; 注册账号」看翻转 +
        辉光效果，注册时把两次密码填得不一样会打出红字错误行。
      </p>
      <div class="ta-demo__stage">
        <MatrixRain :opacity="0.14" color="#00c840" accent="#7dffb0" background="rgba(2, 13, 6, 0.08)" />
        <TerminalAuth v-model:mode="mode" class="ta-demo__panel" @submit="onSubmit" @mismatch="onMismatch" />
        <TerminalAuth
          v-model:mode="mode2"
          class="ta-demo__panel"
          accent="#00ffe0"
          login-title="安全终端"
          register-title="申请通行证"
          login-action="[ 验证身份 ]"
          register-action="[ 签发通行证 ]"
          :scanline="true"
          @submit="onSubmit"
        />
      </div>
      <p class="ta-demo__hint">
        最近一次操作：<code>{{ lastAction }}</code>
      </p>
    </section>

    <DemoPreview class="ta-preview">
      <LevaPlayground
        name="TerminalAuth"
        :component="TerminalAuth"
        :schema="TerminalAuthSchema"
        :presets="{ mode: 'login' }"
        :listeners="{ submit: (payload: unknown) => (lastAction = `submit ${JSON.stringify(payload)}`) }"
        stage-class="is-dark"
        :stage-style="stageStyle"
      />
    </DemoPreview>

    <p class="demo-note">
      <span>
        面板里 <code>mode</code> 切登录/注册，<code>accent</code> 换荧光色，<code>sysTag</code> /
        两套标题 / 按钮文案 / 切换链接文案 / 提示符都是字符串控件，<code>strength</code> 控制强度条、
        <code>logs</code> 控制日志行、<code>scanline</code> 是面板内的扫描线。
        提交走 <code>submit</code> 事件，两次密码不一致会额外派发 <code>mismatch</code>。
      </span>
    </p>
  </div>
</template>

<script setup lang="ts">
import { ref } from 'vue'
import TerminalAuthSchema from '@melt-js/comps-vue3/src/components/TerminalAuth.propsSchema.json'
import DemoPreview from '../components/DemoPreview.vue'
import LevaPlayground from '../components/LevaPlayground.vue'
import MatrixRain from '../components/MatrixRain.vue'
import { remoteComponent } from '../configs/remote'

const TerminalAuth = remoteComponent('TerminalAuth')

const mode = ref<'login' | 'register'>('login')
const mode2 = ref<'login' | 'register'>('login')
const lastAction = ref('还没操作')

const stageStyle = {
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  height: '640px',
  padding: '24px',
  background: '#020d06',
}

function onSubmit(payload: { mode: string; username: string }) {
  lastAction.value = `${payload.mode} 提交，用户名 ${payload.username || '（空）'}`
}

function onMismatch() {
  lastAction.value = '两次密码不一致'
}
</script>

